func (p *predicateParser) getFunctionAndArgs(callExpr *ast.CallExpr) (interface{}, []ast.Expr, error) {
	switch f := callExpr.Fun.(type) {
	case *ast.Ident:

	case *ast.Ident:
		// Plain function with a single identifier name.
		fn, err := p.getFunction(f.Name)
