}

type RegexpReplaceExpr struct { Input Expr; Pattern, Replacement string; re *regexp.Regexp }
func (e RegexpReplaceExpr) String() string { return "regexp.replace("+e.Input.String()+", "+strconv.Quote(e.Pattern)+", "+strconv.Quote(e.Replacement)+")" }
func (RegexpReplaceExpr) Kind() reflect.Kind { return reflect.String }
func (e RegexpReplaceExpr) Evaluate(ctx EvaluateContext) (any,error) {
 v,err:=e.Input.Evaluate(ctx); if err!=nil{return nil,err}
 var out []string
 for _,s:=range v.([]string) { if e.re.MatchString(s) {out=append(out,e.re.ReplaceAllString(s,e.Replacement))} }
